// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
        vm.deal(address(this), 100 ether);
    }

    function testFuzz_property(uint256 deposit, uint256 collectAmount) public {
        vm.assume(deposit <= VALUE_CAP);
        deposit = bound(deposit, 1 ether, 10 ether);
        collectAmount = bound(collectAmount, 0.5 ether, 5 ether);
        if (collectAmount > deposit) collectAmount = deposit;

        address attacker = address(this);
        vm.deal(attacker, deposit);

        // Seed the caller's Acc, then advance time so Collect passes unlockTime.
        vm.prank(attacker);
        c.Put{value: deposit}(0);
        vm.warp(block.timestamp + 1);

        uint256 beforeBalance = __invmut_c_Acc_balance(attacker);
        vm.prank(attacker);
        bool ok; try c.Collect{value: 0}(collectAmount) { ok = true; } catch { ok = false; }
        require(ok, "Collect reverted");

        uint256 afterBalance = __invmut_c_Acc_balance(attacker);
        assertTrue(afterBalance >= beforeBalance - collectAmount);
    }

    receive() external payable {
        // Re-enter Collect once from inside the payout, before the outer frame updates Acc.
        if (address(c).balance >= 0.5 ether) {
            c.Collect(0.5 ether);
        }
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
